// As medições abaixo pertencem aos cenários didáticos descritos em cada aula.
function flow(nodes, rows) {
  return rows.map(([active, label, title, change, metrics, explanation, check, idea, code]) => ({
    active, nodes, label, title, change, metrics,
    body: explanation + '\n\n' + check,
    idea, ...(code ? { code } : {}),
  }));
}

export const platformCases = {
  'mistura-de-especialistas': {
    scenario: 'Em um lote de 512 tokens, cada token passa por dois dos oito especialistas. Um especialista é uma parte da camada do modelo com seus próprios pesos. Mude a distribuição dos pedidos e veja qual especialista segura o lote.',
    minutes: 19,
    source: { label: 'Mistral AI · Mixtral of Experts', url: 'https://arxiv.org/abs/2401.04088' },
    steps: flow(['Roteador', 'Experts', 'Combinação'], [
      [0, 'Dimensionar', 'O que precisa caber na memória?', 'A equipe separa pesos residentes de pesos usados por token.', [['Pesos totais','10 bi'],['Ativos/token','4 bi'],['Pesos BF16','20 GB']], 'Cada especialista guarda seus próprios pesos. Juntos, os oito guardam 8 bilhões de números. Há mais 2 bilhões que todos os tokens usam. Como BF16 ocupa dois bytes por número, só os pesos somam 20 GB decimais.', 'Para processar um token, o roteador escolhe dois especialistas. A placa ainda precisa guardar os demais pesos se todos os especialistas morarem nela. Além dos pesos, reserve memória para os dados de cada conversa e para as contas em andamento.', 'Top-2 reduz o trabalho das camadas esparsas. Os oito experts precisam continuar acessíveis.'],
      [0, 'Pontuar', 'O roteador escolhe dois destinos por token', 'Para um token, E1 e E6 recebem as duas maiores pontuações.', [['Experts pontuados','8'],['Escolhidos','2'],['Peso de E1','0,70']], 'O roteador recebe o vetor oculto do token. Nesta camada de exemplo, seleciona dois scores e renormaliza os pesos selecionados para 0,70 e 0,30. Guarde a posição do token, os dois IDs e os coeficientes para reconstruir a saída.', 'Inspecione uma amostra por camada e posição. Forçar todos os tokens de uma requisição para o mesmo expert mudaria o cálculo do modelo. A seleção acontece novamente para cada token e camada MoE.', 'O roteamento é aprendido. Redirecionar para um expert menos ocupado altera o resultado.'],
      [1, 'Agrupar', 'Troque ordem de chegada por blocos de cálculo', 'Os 512 tokens passam a 1.024 atribuições agrupadas por expert.', [['Tokens','512'],['Atribuições','1.024'],['Média/expert','128']], 'Cada token ocupa duas posições no buffer de despacho. Agrupe por ID do expert, forme matrizes de ativações e preserve um mapa de retorno. Com distribuição uniforme, cada expert executa uma multiplicação para 128 linhas.', 'Confirme que a soma dos tamanhos dos grupos é 1.024. Teste um token com escolhas em ordem invertida e outro que compartilha um expert com seu vizinho. Ambos precisam voltar para sua posição original.', 'A contagem de atribuições cresce com o top-k e difere do número de tokens do lote.'],
      [2, 'Combinar', 'Os dois ramos voltam ao token original', 'E1 devolve 6 e E6 devolve 2 nesta coordenada. Com pesos de 0,70 e 0,30, o token de origem recebe 4,8 nessa coordenada.', [['Saída E1','6,0'],['Saída E6','2,0'],['Combinada','4,8']], 'Reordene os resultados com o mapa de retorno e pondere cada vetor com seu coeficiente. Numa dimensão simples, 0,70 × 6 + 0,30 × 2 = 4,8. A operação real agrega vetores antes de seguir para o restante do bloco.', 'Compare um lote pequeno com uma implementação de referência em maior precisão. Um índice trocado pode manter a latência normal e produzir respostas incorretas. Teste também diferenças numéricas próprias do BF16.', 'Verificar posições e pesos é tão importante quanto medir vazão.'],
      [1, 'Medir', 'Compare a distribuição com o tempo de cauda', 'O replay de atendimento geral produz grupos parecidos.', [['Média/expert','128'],['Maior grupo','144'],['Camada p95','3,4 ms']], 'Em cada iteração, conte as linhas por expert e calcule máximo dividido pela média. Neste replay a razão é 1,125. Registre duração dos kernels e tempo entre despacho e recombinação, separados por prefill e decode.', 'Preserve a mistura de idiomas e tarefas do produto. Um benchmark sintético com grupos artificialmente iguais elimina justamente a variação de roteamento que a operação deve suportar.', 'A média estável pode esconder uma camada lenta ou um lote enviesado.'],
      [1, 'Reproduzir', 'Uma campanha concentra consultas no mesmo domínio', 'E6 recebe 384 linhas. Mesmo depois que os outros experts terminam, a camada ainda espera o resultado de E6.', [['Maior grupo','384'],['Máx./média','3,0×'],['Camada p95','7,9 ms']], 'No pico de perguntas especializadas, o número de tokens e o top-k permanecem iguais. Um expert recebe três vezes a média. Os demais terminam cedo e a combinação aguarda o último resultado.', 'Compare os histogramas de grupos antes e depois da campanha. Verifique se a espera vem do kernel do expert, da comunicação ou da fila a montante antes de mudar a distribuição dos pesos.', 'O domínio do tráfego pode mudar o custo de servir a mesma quantidade de tokens.'],
      [1, 'Reequilibrar', 'Duas cópias idênticas atendem o expert popular', 'As 384 linhas de E6 são divididas em dois grupos de 192.', [['Cópias E6','2'],['Linhas/cópia','192'],['Pesos extras','2 GB']], 'No teste com espaço em outro dispositivo, replique um expert lógico de 1 bilhão de pesos BF16 e divida suas atribuições entre cópias físicas. Preserve os IDs lógicos e os coeficientes do roteador. A redundância consome memória e pode reduzir a capacidade de KV cache.', 'Carregue a cópia antes de publicar o novo mapa. Confira a equivalência das saídas e escolha a distribuição considerando memória livre, tráfego de rede e número de linhas. Um mapa atualizado por apenas parte dos workers pode trocar os destinos.', 'Replicar os mesmos pesos alivia o desequilíbrio preservando a função do expert.'],
      [2, 'Aceitar', 'Teste mudanças bruscas de mistura antes do rollout', 'O replay misto volta a atender a meta de 5 ms por camada no p95.', [['Camada p95','4,6 ms'],['Meta p95','5,0 ms'],['Misturas','3']], 'Execute os replays geral, especializado e alternado com a mesma concorrência. Meça a cauda e a memória disponível para contexto em cada um. Refaça as comparações de saída nos tokens para os quais a réplica entrou no caminho.', 'Publique sob canário com mapa anterior disponível. Recuar é apropriado se a camada acelera e o TTFT global piora por perda de cache. Registre também tempo de convergência quando outra especialidade se torna popular.', 'A unidade de aceitação final é a requisição do usuário, além do microbenchmark da camada.'],
    ]),
  },
  'paralelismo-de-especialistas': {
    minutes: 21,
    scenario: 'Quatro placas dividem oito especialistas. A cada rodada, chegam 512 tokens. Cada token envia seus dados a dois especialistas e recebe dois resultados. Use esse caminho para calcular quanto passa pela rede.',
    source: { label: 'vLLM · expert parallel deployment e EPLB', url: 'https://docs.vllm.ai/en/stable/serving/expert_parallel_deployment/' },
    steps: flow(['Origem', 'All-to-all', 'Rank destino'], [
      [2, 'Posicionar', 'Desenhe o mapa lógico e físico', 'Cada rank começa com dois dos oito experts.', [['Ranks','4'],['Experts/rank','2'],['Top-k','2']], 'Distribua os experts E0–E7 entre os quatro processos. A parte de atenção segue o particionamento escolhido para o modelo. Registre o rank de origem de cada token e o proprietário de cada expert.', 'Em um lote de teste, reproduza manualmente um token que escolhe um expert local e um remoto. Uma GPU sozinha só atende esse token se os pesos de ambos estiverem presentes ou se puder enviar a ativação ao rank correto.', 'Expert parallelism distribui experts entre processos de um grupo de execução.'],
      [0, 'Contar', 'Dimensione bytes por atribuição', 'O lote cria 1.024 destinos antes do filtro local.', [['Atribuições','1.024'],['Vetor','8 KiB'],['Payload ida','8 MiB']], 'Cada vetor ocupa 4.096 × 2 = 8.192 bytes. Em um despacho ingênuo há 512 × 2 = 1.024 vetores, 8 MiB globais de payload lógico. O retorno tem volume semelhante. Há ainda índices, alinhamento e cabeçalhos.', 'Não multiplique esse volume global por quatro. Conte origens e destinos e desconte atribuições locais para estimar tráfego na interconexão. Kernels com agregação por rank podem reduzir duplicações.', 'Bytes lógicos, bytes remotos e bytes medidos na interface são grandezas diferentes.'],
      [1, 'Despachar', 'Envie tamanhos variáveis a cada rank', 'Com 75% de atribuições remotas, a ida cruza a malha com 6 MiB.', [['Remotas','768'],['Ida remota','6 MiB'],['Volta remota','6 MiB']], 'Ordene os tokens por destino e prepare contagens e deslocamentos. Na troca all-to-all, cada origem envia uma quantidade diferente a cada destino. As contribuições locais podem usar o caminho de memória do próprio rank.', 'Some os bytes por par de ranks. A taxa agregada da malha não revela o tempo de uma conexão saturada. Meça duração de dispatch, cálculo e combine na mesma iteração.', 'A rota mais carregada pode definir o tempo do grupo inteiro.'],
      [2, 'Executar', 'Sincronize o retorno com a ordem original', 'O primeiro ensaio termina em 4,8 ms de ponta a ponta da camada.', [['Despacho','1,2 ms'],['Cálculo crítico','2,5 ms'],['Retorno','1,1 ms']], 'Cada destino aplica os experts locais em grupos de linhas. Os resultados retornam à origem para combinar os ramos com os pesos do roteador. Neste primeiro ensaio os três intervalos são medidos em série na mesma iteração.', 'Verifique tokens com dois destinos remotos, um destino local e grupos vazios. Compare com execução de referência e meça o máximo entre ranks usando a mesma janela. Percentis independentes dos estágios não se somam.', 'O caminho crítico pode alternar entre comunicação e cálculo conforme o lote.'],
      [2, 'Localizar', 'O rank 3 atrasa os demais', 'No tráfego de suporte técnico, o rank 3 recebe metade das linhas.', [['Linhas/rank 3','512'],['Média/rank','256'],['Camada p95','9,2 ms']], 'Cruze contagem por expert, rank e camada. Se dois experts muito procurados estão no mesmo dispositivo, o rank acumula trabalho mesmo sem haver falha no enlace. Compare seus kernels e o tempo ocioso dos demais.', 'Repita o mesmo lote trocando o posicionamento físico e preservando os IDs lógicos. Se o atraso acompanha os experts, a hipótese de skew ganha força. Se continua na mesma placa, examine o nó e sua interconexão.', 'Separar skew lógico de defeito físico evita uma migração de pesos inútil.'],
      [2, 'Remapear', 'Redistribua pesos com uma janela representativa', 'Após o novo mapa, o rank mais carregado passa de 512 para 308 linhas.', [['Pico/rank','308'],['Máx./média','1,20×'],['Camada p95','6,1 ms']], 'Ative o balanceamento do runtime quando suportado. No vLLM, o EPLB observa carga e ajusta o mapeamento físico periodicamente. Teste primeiro um remapeamento com a memória disponível e avalie depois o custo de experts redundantes.', 'Meça o tempo de migração e a duração típica de um pico. Reequilibrar mais rápido que a estabilização do tráfego pode consumir a própria largura de banda necessária ao serving. Valide o novo mapa em todos os ranks.', 'O custo de mover pesos precisa ser recuperado durante a vida útil do novo mapa.'],
      [1, 'Isolar', 'Uma troca de nó muda o caminho do coletivo', 'A troca de um rank para outro host eleva o p95 para 11,4 ms.', [['Carga máx./média','1,19×'],['Despacho p95','4,7 ms'],['Camada p95','11,4 ms']], 'A distribuição dos experts permanece saudável, mas as transferências passam a cruzar uma rede mais lenta. Confira a topologia efetiva do job e a interface realmente usada pelo backend coletivo. Uma alocação com quatro GPUs disponíveis pode atravessar domínios de rede distintos.', 'Compare o replay no nó antigo e na nova topologia. Reserve um grupo compatível e aqueça a réplica de substituição. Um rank isolado indisponível compromete o grupo, então retire a réplica afetada do tráfego até a recuperação.', 'Capacidade por número de GPUs ignora a comunicação exigida entre elas.'],
      [0, 'Validar', 'Meça o grupo de substituição sob tráfego realista', 'A colocação no mesmo domínio traz a cauda novamente para a meta.', [['Camada p95','6,3 ms'],['Meta p95','7 ms'],['Ranks prontos','4/4']], 'Reproduza prefill longo, decode com lotes pequenos e mudanças de especialidade. Compare os backends coletivos suportados na plataforma. Algoritmos otimizados para alto volume podem piorar a latência em lotes curtos.', 'Simule perda de um rank, drene o grupo inteiro e confira a folga nas réplicas restantes. Registre no plano de capacidade o tamanho do domínio de falha e o tempo de aquecimento de todos os ranks.', 'Um grupo EP só oferece capacidade útil quando todos os participantes necessários podem trabalhar e se comunicar.'],
    ]),
  },
  'paralelismo-de-modelo': {
    minutes: 20,
    scenario: 'Um modelo com 32 bilhões de pesos precisa responder a 60 pedidos por segundo. A equipe tem quatro máquinas. Cada uma tem duas GPUs de 48 GiB. Trocar dados entre duas placas da mesma máquina é mais rápido do que atravessar a rede.',
    source: { label: 'vLLM · paralelismo tensorial e de pipeline', url: 'https://docs.vllm.ai/en/stable/serving/parallelism_scaling/' },
    steps: flow(['Partições', 'Pipeline', 'Réplicas'], [
      [0, 'Estimar', 'O modelo cabe em uma placa?', 'Os pesos sozinhos excedem os 48 GiB de uma GPU.', [['Pesos BF16','59,6 GiB'],['VRAM/GPU','48 GiB'],['Nós','4']], '32 bilhões × 2 bytes dão 64 GB decimais, ou 59,6 GiB. Ainda faltam estado da execução, buffers temporários e KV cache. Uma réplica completa por placa não cabe nesta precisão.', 'Faça a estimativa com o checkpoint real e acompanhe a memória alocada pelo runtime durante o prefill mais longo admitido. Dividir o total de pesos pela VRAM é apenas o primeiro limite inferior.', 'Escolha primeiro um particionamento que carregue o modelo com espaço para atender.'],
      [0, 'Testar TP', 'Divida as matrizes dentro do mesmo nó', 'Com TP=2, cada GPU mantém aproximadamente 29,8 GiB de pesos.', [['TP','2'],['Pesos/GPU','29,8 GiB'],['Réplicas','1']], 'Distribua partes das matrizes entre duas GPUs do mesmo nó. As GPUs calculam suas partições e trocam resultados parciais por coletivos em diferentes camadas. A divisão real pode incluir componentes replicados e restrições de divisibilidade das cabeças.', 'Meça o custo das coletivas e o pico de memória. O espaço teórico de 18,2 GiB por GPU precisa acomodar mais que o KV cache. Confirme os tamanhos de sequência e concorrência suportados antes de aceitar o perfil.', 'Tensor parallelism troca memória e trabalho por comunicação recorrente dentro das camadas.'],
      [1, 'Testar PP', 'Compare uma divisão por grupos de camadas', 'PP=2 coloca metade das camadas em cada GPU e transfere ativações na fronteira.', [['Estágios','2'],['Micro-lotes','1'],['Ocupação ideal','50%']], 'Se os estágios duram o mesmo tempo e há um único micro-lote independente, um estágio espera o outro. No modelo simples de pipeline, ocupação é m/(m+p−1), com m micro-lotes e p estágios. A geração autorregressiva e o batching real modificam esse perfil.', 'Reproduza latência de um usuário e vazão sob concorrência separadamente. Particione por tempo de computação e memória observados, pois dividir apenas pela quantidade de camadas pode deixar um estágio mais lento.', 'Pipeline parallelism reduz a frequência de comunicação entre estágios, mas pode deixar capacidade ociosa.'],
      [1, 'Preencher', 'Faça mais solicitações independentes atravessarem o pipeline', 'Com sete micro-lotes e dois estágios ideais, a ocupação chega a 87,5%.', [['Micro-lotes','7'],['Estágios','2'],['Ocupação ideal','87,5%']], 'No cálculo simplificado, sete micro-lotes ocupam oito intervalos até o último sair. Na prática, prefill e decode não têm durações iguais e solicitações terminam em instantes diferentes. Observe ociosidade e profundidade de fila em cada estágio.', 'Compare no mesmo corpus TP=2 e PP=2 com a meta de TTFT do produto. Neste cenário, o replay escolhe TP=2 por sustentar mais req/s sob a meta. Em uma interconexão diferente, a escolha pode mudar.', 'A fórmula explica a bolha. O dimensionamento depende da vazão medida sob o SLO.'],
      [2, 'Replicar', 'Escale o grupo já validado', 'O replay mede 24 req/s por réplica TP=2, já dentro do SLO.', [['Req/s por grupo','24'],['Grupos ativos','3'],['Capacidade','72 req/s']], 'Suba três cópias independentes de duas GPUs e distribua requisições entre grupos. Cada cópia possui seus próprios pesos e KV cache. Preserve afinidade quando a reutilização de prefixo compensar, observando o tamanho das filas.', 'Compare a capacidade agregada prevista com teste de carga. Neste ensaio, 60 req/s ocupam 83,3% da capacidade de três grupos. A reserva de um quarto nó ainda não representa capacidade imediata se os pesos estiverem frios.', 'Uma réplica adiciona capacidade independente. Aumentar TP dentro da mesma réplica muda sua geometria.'],
      [2, 'Falhar', 'A perda de uma GPU derruba seu grupo TP', 'Com dois grupos disponíveis faltam 12 req/s no pico.', [['Grupos prontos','2'],['Capacidade','48 req/s'],['Déficit','12 req/s']], 'Quando um rank falha, retire os dois membros da réplica da rotação. Evite encaminhar para o outro rank isoladamente. Se o tráfego permanece em 60 req/s e a capacidade é 48, uma fila sem limite cresce mesmo com os outros nós saudáveis.', 'Separe pedidos interativos com prazo curto do trabalho adiável. Aplique admissão antes de alocar KV e teste se o cliente recebe o motivo da recusa. Repetir imediatamente a mesma carga aumenta a fila.', 'O domínio de falha da réplica é o conjunto de dispositivos participantes.'],
      [0, 'Recuperar', 'Aqueça o quarto nó com a revisão correta', 'A reserva leva 90 s para carregar, validar e receber tráfego.', [['Aquecimento','90 s'],['Déficit','12 req/s'],['Acúmulo teórico','1.080 req']], 'Certifique-se de que todas as placas compartilham a revisão de pesos, o tokenizador e o ambiente de execução. Valide coletivos e um prompt representativo antes de registrar o endpoint. Uma réplica pronta no plano de controle pode ainda não estar apta a gerar dentro da meta.', 'Sem rejeição ou cancelamento, 12 × 90 pedidos se acumulariam. Quando a capacidade sobe a 72 req/s, a folga de 12 req/s levaria mais 90 s para drenar essa fila. Solicitações já vencidas devem ser descartadas.', 'Meça tempo até capacidade útil e o tempo adicional necessário para drenar a fila.'],
      [2, 'Reservar', 'Projete o pico com uma réplica indisponível', 'Quatro réplicas prontas sustentam o pico com uma em falha.', [['Grupos quentes','4'],['Capacidade N−1','72 req/s'],['Pico','60 req/s']], 'Neste cenário, quatro grupos quentes entregam 96 req/s no total e 72 req/s após perder um nó. Compare o custo dessa reserva com a meta de disponibilidade e com o custo de pausar trabalho de menor prioridade.', 'Interrompa um nó durante o pico de teste, preserve a distribuição de prompt e saída, acompanhe p95 e taxa de conclusão. Refaça as contas quando mudar quantização, topologia de rede ou comprimento das respostas.', 'O plano de recuperação deve ser testado com a mesma carga que se pretende prometer.'],
    ]),
  },
  'replicas-e-autoscaling': {
    minutes: 18,
    scenario: 'O serviço começa com quatro cópias prontas. Cada uma atende 16 pedidos por segundo dentro do prazo, mas a equipe opera perto de 12 para deixar folga. Uma cópia nova só começa a ajudar depois de dois minutos.',
    source: { label: 'Kubernetes · algoritmo e comportamento do HPA', url: 'https://kubernetes.io/docs/concepts/workloads/autoscaling/horizontal-pod-autoscale/' },
    steps: flow(['Admissão', 'Controlador', 'Réplicas'], [
      [0, 'Medir', 'Use o trabalho que chega à GPU', 'O pico inicial ocupa três quartos da capacidade testada.', [['Chegada','48 req/s'],['Prontas','4'],['Carga/réplica','12 req/s']], 'Classifique os pedidos por tokens de entrada e saída antes de interpretar req/s. Um endpoint com prompts longos pode saturar o prefill mesmo recebendo menos solicitações. Neste replay a distribuição de tokens é mantida fixa.', 'Encontre a maior taxa que preserva o p95 de TTFT e a taxa de sucesso. Use esse ponto e uma margem operacional para definir o alvo. Métricas de CPU podem continuar baixas enquanto os workers esperam a GPU.', 'A métrica de escala precisa acompanhar a demanda limitante do perfil de tráfego.'],
      [1, 'Calcular', 'Converta o pico em uma recomendação discreta', 'Uma campanha eleva a entrada para 72 req/s.', [['Chegada','72 req/s'],['Alvo/réplica','12 req/s'],['Desejadas','6']], 'Para uma métrica de taxa por réplica, a aproximação do HPA é teto de réplicas atuais × valor observado/alvo. Aqui a média salta a 18 req/s por réplica e teto de 4 × 18/12 é 6. A métrica de chegada precisa incluir rejeições para que a demanda não desapareça do sinal.', 'Inspecione janela de coleta, tolerância, limites configurados e amostras ausentes. A recomendação calculada não implica a existência de nós GPU disponíveis nem início instantâneo dos pods.', 'O sinal usado pelo controlador e a capacidade que o usuário já recebe são medidas separadas.'],
      [2, 'Aquecer', 'Conte a fila durante os dois minutos de espera', 'Duas réplicas foram solicitadas, mas apenas quatro podem atender.', [['Ativas','4/6'],['Capacidade','64 req/s'],['Déficit','8 req/s']], 'Enquanto a taxa é 72 e a capacidade quente 64, a fila cresce pelo menos 8 req/s se tudo for aceito. Em 120 s seriam 960 pedidos. Essa estimativa presume serviço contínuo e ignora desistências e variação dos tokens.', 'Verifique eventos do scheduler, cache local de pesos, inicialização do CUDA e primeira geração. Registre percentis separados para espera por GPU e carregamento do modelo para decidir entre reservar nós ou pré-carregar pesos.', 'Uma réplica em inicialização não pode amortizar o pico que já chegou.'],
      [0, 'Conter', 'Limite a fila pelo prazo restante', 'O gateway passa a admitir uma fila de no máximo 64 pedidos neste ensaio.', [['Fila máxima','64 req'],['Serviço quente','64 req/s'],['Espera aproximada','1 s']], 'Se uma solicitação nova chega atrás de 64 pedidos equivalentes e a frota despacha 64/s, só a espera de fila é da ordem de 1 s. Defina um limite menor se rede, prefill e geração já gastarem boa parte do prazo do cliente.', 'Devolva recusa explícita quando faltar orçamento. Verifique se o cliente aplica atraso antes de repetir e se as solicitações já canceladas saem da fila. Controle separadamente tráfego com prioridade e uso em lote.', 'Fazer o usuário esperar por um trabalho que vai expirar consome a capacidade de quem ainda pode ser atendido.'],
      [2, 'Drenar', 'A capacidade adicional chega antes de a fila sumir', 'Com seis réplicas, há 24 req/s disponíveis para reduzir o atraso.', [['Prontas','6'],['Capacidade','96 req/s'],['Folga','24 req/s']], 'A fila limitada de 64 pedidos levaria aproximadamente 2,7 s para zerar a uma folga constante de 24/s. Se a fila anterior fosse de 960, a drenagem levaria 40 s. O ganho aparece primeiro na idade do item mais antigo e depois na distribuição de latência.', 'Compare os tempos medidos com essas estimativas. Se a fila não cai, examine afinidade de prefixo, réplica fria e concentração de pedidos caros. Um balanceador por contagem de conexões pode esconder carga desigual.', 'A entrada de uma réplica nova não garante distribuição imediata e uniforme dos pedidos.'],
      [1, 'Estabilizar', 'Evite remover as réplicas assim que a taxa cai', 'Na cauda da campanha a taxa volta para 36 req/s.', [['Chegada','36 req/s'],['Desejo bruto','3'],['Janela escolhida','300 s']], 'No cenário, a equipe configura uma janela de estabilização de cinco minutos para scale-down. Dentro dela o controlador considera recomendações recentes. Isso reduz o risco de remover capacidade quente durante um vale curto.', 'Teste um segundo pico com intervalo menor que a janela. Acompanhe minutos de GPU ociosa e violações de latência. Um limite de pods removidos por intervalo evita que uma única decisão retire várias sessões em streaming ao mesmo tempo.', 'Escolha a janela comparando o período real das rajadas com o custo de reaquecimento.'],
      [1, 'Antecipar', 'Reserve capacidade para um pico anunciado', 'Cinco réplicas já aquecidas sustentam o degrau inicial de 72 req/s.', [['Reserva quente','5'],['Capacidade','80 req/s'],['Margem inicial','8 req/s']], 'Para uma campanha agendada, eleve o mínimo antes do início e verifique se os nós conseguiram alocar as GPUs. Cinco réplicas reduzem a necessidade de fila durante o aquecimento da sexta. A reserva pode ser removida após a janela do evento.', 'Introduza uma falha de réplica na carga de teste. Quatro réplicas restantes entregam 64/s. Para prometer 72/s mesmo após uma falha simples, mantenha pelo menos seis quentes neste perfil.', 'Antecipação e escala reativa tratam escalas de tempo diferentes.'],
      [0, 'Aceitar', 'Avalie a política em um replay com falha', 'O ensaio final começa com seis réplicas e perde uma durante o pico.', [['N−1','80 req/s'],['Pico previsto','72 req/s'],['Folga N−1','8 req/s']], 'Reproduza a curva de chegada sem deixar o cliente reduzir a taxa quando a fila cresce. Desligue uma réplica, injete uma falha de coleta e mantenha pedidos longos na mistura. Conte recusas e timeouts no denominador de sucesso.', 'Aprovação exige que fila, vazão útil e disponibilidade por classe fiquem nas bandas definidas e que o custo de GPU permaneça no orçamento. Recalibre 16 req/s quando houver outra revisão de modelo ou mudança de contexto.', 'Um teste sustentado sob falha separa capacidade nominal de capacidade disponível.'],
    ]),
  },
  'saude-e-prontidao': {
    minutes: 18,
    scenario: 'Três réplicas com modelos grandes passam por uma atualização. Carregar os pesos leva de 110 a 190 s no p95 das implantações de teste. O prazo de terminação inicial é 30 s. Os tempos e tentativas ilustram a interação entre modelo, sondas e balanceador.',
    source: { label: 'Kubernetes · startup, liveness e readiness probes', url: 'https://kubernetes.io/docs/concepts/workloads/pods/probes/' },
    steps: flow(['Inicialização', 'Prontidão', 'Drenagem'], [
      [0, 'Observar', 'O servidor aceita TCP antes da primeira geração', 'A porta abre em 8 s enquanto os pesos ainda estão carregando.', [['Porta aberta','8 s'],['Carga típica','110 s'],['Réplicas novas','1']], 'O processo pode abrir o socket antes de inicializar workers e carregar o modelo. Uma sonda TCP nesse instante diria que a porta responde, embora a primeira geração falhe ou espere muito além do prazo.', 'Registre marcos de processo iniciado, pesos disponíveis, primeiro prefill e primeira saída. Compare o tempo até o pod entrar no Service com o tempo até atender um prompt curto dentro do SLO.', 'Saúde do processo, possibilidade de receber tráfego e qualidade sob carga são sinais distintos.'],
      [0, 'Reproduzir', 'O kubelet reinicia um processo que fazia progresso', 'A sonda de liveness falha três vezes sem tolerar 110 s de carga.', [['Período','10 s'],['Falhas seguidas','3'],['Reinícios','4']], 'Sem startup probe adequada, liveness pode considerar defeituoso um worker ainda não inicializado. O processo reinicia, descarta o trabalho de carga e repete o mesmo ciclo. Nas quatro tentativas de exemplo, os logs avançam até aproximadamente o mesmo marco.', 'Alinhe os eventos do kubelet com os logs do runtime. Distinga um reinício solicitado pela sonda de um OOM ou falha do driver. Aumentar o prazo de todas as sondas indiscriminadamente mascararia um travamento após a inicialização.', 'A causa de morte e o ponto de progresso indicam se o problema é a tolerância de startup.'],
      [0, 'Proteger', 'Dê à inicialização seu próprio orçamento', 'Uma startup probe com 24 tentativas a cada 10 s admite cerca de 240 s.', [['Período','10 s'],['Falhas permitidas','24'],['Orçamento','≈240 s']], 'No Kubernetes, a startup probe retarda liveness e readiness até obter sucesso. Escolha a tolerância usando a distribuição de inicialização, incluindo download frio e pressão de disco. A aproximação período × limite serve para planejamento e depende do agendamento das tentativas.', 'Force uma carga lenta de 190 s e confirme que a réplica progride sem reiniciar. Em seguida provoque um bloqueio definitivo e verifique a substituição após esgotar o orçamento. Registre o motivo da falha.', 'Uma startup probe deve tolerar carga lenta e ainda ter um limite para inicialização travada.'],
      [1, 'Aquecer', 'Abra o tráfego depois de validar a revisão', 'O primeiro prefill no novo pod custa 1,4 s e os seguintes, 160 ms neste teste.', [['Primeiro prefill','1,4 s'],['Aquecido','160 ms'],['Réplica pronta','1']], 'Execute um canário interno pequeno durante o aquecimento, validando modelo servido, tokenizador e participação de todos os ranks. Armazene o resultado em estado local de prontidão. A consulta da sonda regular pode ser barata e ler esse estado.', 'Meça o custo total de probes multiplicado pelo tamanho da frota. Fazer geração cara a cada consulta de liveness pode consumir slots em pleno incidente. Use uma sonda sintética separada para SLO contínuo.', 'O teste caro valida a transição para pronto. Um sinal barato publica o resultado.'],
      [1, 'Distinguir', 'Uma dependência compartilhada fica lenta', 'O serviço auxiliar sobe de 45 para 900 ms e os três pods seguem vivos.', [['Dependência p95','900 ms'],['Liveness OK','3/3'],['Timeout auxiliar','400 ms']], 'Reiniciar todas as réplicas não recupera uma dependência externa lenta. A liveness deve detectar uma falha local que reinício pode corrigir. Para recursos necessários apenas a uma rota, aplique fallback ou rejeição nessa rota e mantenha trabalho independente disponível.', 'Simule queda da dependência e examine a capacidade restante. Se ela for indispensável a todas as respostas, defina explicitamente o comportamento de admissão e mensagem de indisponibilidade para evitar fila ilimitada.', 'Amarrar a sobrevivência de todo pod a um sistema compartilhado pode criar uma tempestade de reinícios.'],
      [2, 'Drenar', 'Retire a réplica sem interromper streams curtos', 'Ao iniciar terminação, 12 streams ainda usam o pod.', [['Streams ativos','12'],['Graça inicial','30 s'],['Duração restante p95','48 s']], 'Marque a aplicação como em drenagem e pare de admitir novos pedidos. A remoção do endpoint e a reação de proxies levam tempo e podem acontecer em paralelo à terminação. Rejeite trabalho novo também no processo e preserve os streams já aceitos até seu prazo.', 'Cronometre propagação do balanceador, execução de preStop e saída dos workers. O relógio de terminationGracePeriodSeconds inclui o hook. Um sleep fixo de 30 s em um prazo de 30 s deixa os workers sem margem.', 'Remover a réplica do Service não cancela nem conclui automaticamente conexões já estabelecidas.'],
      [2, 'Dimensionar', 'Orce o período de graça a partir das últimas sessões', 'O teste reserva 75 s e encerra trabalho que ultrapassar o prazo da aplicação.', [['Propagação p99','5 s'],['Prazo do stream','60 s'],['Graça','75 s']], 'Para este produto, streams possuem prazo de 60 s. Reserve 5 s de propagação mais 60 s para o último trabalho permitido e 10 s para fechar conexões e persistir resultados. Se a distribuição real exceder a hipótese, trate como falha de dimensionamento.', 'Mate o pod antes e depois do sinal final. Confira que o cliente distingue resposta concluída de stream truncado e que o reenvio da operação usa a regra de idempotência do produto.', 'O tempo de encerramento deve caber no prazo de infraestrutura e no contrato do cliente.'],
      [1, 'Verificar', 'Execute um rollout com a pior inicialização do ensaio', 'A frota mantém duas réplicas úteis enquanto a terceira é substituída.', [['Disponíveis mín.','2'],['Startup p95','190 s'],['Streams truncados','0/120']], 'Combine carga de tráfego, cold start, indisponibilidade do serviço auxiliar e terminação. Monitore o mínimo de réplicas prontas ao longo do tempo, além da taxa de resposta e do número de reinícios durante cada fase.', 'Neste ensaio 120 streams terminaram dentro do prazo. Isso valida o cenário amostrado. Amplie a duração, os tamanhos de saída e a variedade de proxies antes de assumir uma taxa de falha aceitável para milhões de usuários.', 'A validação testa transições entre estados, especialmente durante atualização e falha simultâneas.'],
    ]),
  },
  'observabilidade': {
    minutes: 19,
    scenario: 'O chat recebe 100 pedidos por segundo. Em pelo menos 95% deles, o primeiro token deve aparecer antes de 800 ms. Compare três momentos, o envio pelo navegador, o início do trabalho no servidor e a chegada da resposta.',
    source: { label: 'vLLM · métricas de produção e histogramas', url: 'https://docs.vllm.ai/en/stable/usage/metrics/' },
    steps: flow(['Cliente', 'Fila', 'Engine'], [
      [0, 'Definir', 'O primeiro token precisa chegar à tela', 'A linha de base distingue observação no cliente e no servidor.', [['Cliente p95','590 ms'],['Servidor p95','480 ms'],['Meta p95','800 ms']], 'No navegador, anote quando o pedido saiu e quando apareceu o primeiro texto. No servidor, anote quando recebeu o pedido e quando enviou a primeira parte. A diferença ajuda a encontrar a espera na rede, num serviço que junta os pedaços ou no próprio navegador.', 'Uma mensagem que só avisa que a conexão continua aberta ainda não mostra a resposta. Marque o primeiro texto visível. Conte separadamente quem cancelou ou desistiu por demora. Anote as versões do navegador e do servidor usadas no teste.', 'A medição escolhida precisa corresponder ao sintoma relatado pelo usuário.'],
      [0, 'Agregar', 'Agregue distribuições antes de calcular o percentil', 'Três réplicas recebem volumes diferentes durante 5 min.', [['Janela','5 min'],['Solicitações','30.000'],['Réplicas','3']], 'Com histogramas clássicos Prometheus, some as taxas dos buckets por le antes de calcular o quantil. A média dos p95 por pod dá peso igual a pods que atenderam volumes diferentes. Preserve dimensões estáveis como modelo e rota, com limites de cardinalidade.', 'Confira se o endpoint da versão instalada expõe o histograma e se os limites dos buckets resolvem a faixa do SLO. Para medir a fração abaixo de 800 ms em vez de estimar quantil, use um bucket nesse limite quando disponível.', 'Percentis locais não carregam informação suficiente para calcular o percentil da frota.', 'histogram_quantile(0.95,\n  sum by (le) (rate(vllm:time_to_first_token_seconds_bucket[5m]))\n)'],
      [1, 'Detectar', 'O p95 de TTFT dobra sem aumento de taxa', 'O alerta dispara com distribuição de entradas diferente da linha de base.', [['Entrada','100 req/s'],['Cliente p95','1.220 ms'],['Fila p95','610 ms']], 'Antes de adicionar GPUs, confira os histogramas de tokens de entrada, tokens de saída e cache. Contagem de requisições constante admite trabalho muito diferente. Veja se o erro se concentra em uma versão de prompt, uma rota ou um tenant.', 'Investigue uma janela equivalente anterior e preserve o denominador de tentativas. Um histograma que inclui apenas sucessos pode parecer melhor precisamente porque pedidos longos passaram a expirar.', 'A taxa de requisições e a taxa de trabalho do modelo podem se mover em direções diferentes.'],
      [2, 'Correlacionar', 'Siga um pedido lento com trace distribuído', 'Amostra lenta mostra fila e prefill dominando o caminho crítico.', [['Fila do trace','620 ms'],['Prefill do trace','410 ms'],['Outras etapas','150 ms']], 'Em um pedido individual, os intervalos não sobrepostos até o primeiro token somam 1.180 ms. Propague um identificador entre gateway, scheduler e geração. Conserve uma amostra de pedidos bem-sucedidos rápidos e lentos para comparação e oculte conteúdo sensível.', 'Use spans do mesmo pedido para decompor a duração. Subtrair p95 do servidor de p95 do cliente não estima o p95 da rede, pois os pedidos nessas posições das duas distribuições podem ser diferentes.', 'Um trace sugere uma causa. As distribuições mostram quantos usuários ela afeta.'],
      [2, 'Isolar', 'O template novo repete uma seção de catálogo', 'O p95 de tokens de entrada cresce de 1.200 para 4.800.', [['Antes p95','1.200 tok'],['Depois p95','4.800 tok'],['ITL p95','34 ms']], 'O espaçamento entre tokens depois do início da resposta permanece próximo à linha de base, mas o prefill ficou maior e a fila cresceu. Faça replay com o mesmo conteúdo e a mesma carga, alternando somente a montagem do prompt.', 'Compare prompts serializados por hash e contagem de tokens. Procure a origem dos blocos repetidos e as regras que os adicionaram. Antes de remover conteúdo, valide se citações ou instruções necessárias serão preservadas.', 'TTFT e latência entre tokens apontam para partes diferentes da experiência de geração.'],
      [1, 'Mitigar', 'Separe o tráfego longo enquanto corrige a montagem', 'Uma fila com cota para prompts longos reduz o impacto nos demais.', [['Curto p95','680 ms'],['Longo p95','1.390 ms'],['Recusas longas','1,4%']], 'A mitigação protege a classe curta com concorrência reservada e limite de espera na longa. O resultado precisa ser exibido por classe, pois a melhora do agregado pode ocultar falhas concentradas em poucos clientes.', 'Acompanhe idade das filas e número de pedidos que vencem antes da GPU. Aplique um contrato de degradação para o caminho longo e negocie prioridade pelo custo do trabalho e pelo prazo restante.', 'Um painel agregado pode celebrar uma recuperação que transferiu a falha para uma classe menor.'],
      [2, 'Comparar', 'Valide a correção com shadow e canário', 'Após remover a repetição, o p95 de entrada cai para 1.250 tokens.', [['Entrada p95','1.250 tok'],['Canário p95','610 ms'],['Citações válidas','298/300']], 'Compare a correção e a versão anterior no mesmo conjunto de perguntas com referência. As duas citações inválidas precisam ser comparadas aos resultados do controle e examinadas antes da promoção.', 'Use canário em tráfego representativo para observar filas e caching reais. Valide os segmentos longos e a taxa de erros, além de duração, pois o shadow não reproduz necessariamente a contenção da frota online.', 'Uma correção de desempenho também é uma mudança do conteúdo que o modelo recebe.'],
      [0, 'Fechar', 'Faça o alerta detectar o próximo incidente cedo', 'O p95 final do cliente volta ao orçamento nas duas classes.', [['Curto p95','575 ms'],['Longo p95','742 ms'],['Erro geral','0,18%']], 'Monitore a proporção de tentativas que excedem o limite, com contagem mínima para tráfego esparso. Mantenha alerta de erro e alerta de latência por classe, acompanhados de tokens de entrada por versão. Um painel de diagnóstico deve ligar o sintoma aos traces amostrados.', 'Reproduza o incidente em teste com carga aberta e verifique o disparo e a recuperação do alerta. Documente o que deve ser revertido e quem responde quando a causa é o prompt em vez da infraestrutura.', 'Feche o incidente quando a correção, o sinal e o procedimento tiverem sido exercitados.'],
    ]),
  },
  'rollout-canario': {
    minutes: 18,
    scenario: 'O assistente recebe 200 pedidos por segundo no pico. A equipe testa uma versão nova durante dez minutos. Ela compara os pedidos enviados às duas versões ao mesmo tempo e aceita um aumento de até 0,3 ponto percentual na taxa de falhas.',
    source: { label: 'Google SRE Workbook · Canarying Releases', url: 'https://sre.google/workbook/canarying-releases/' },
    steps: flow(['Controle', 'Canário', 'Decisão'], [
      [0, 'Fixar', 'Versione a unidade que pode ser revertida', 'O manifesto do candidato reúne quatro artefatos identificáveis.', [['Pesos','v8'],['Template','v3'],['Runtime','rev. 42']], 'Fixe pesos, tokenizador, template e runtime com identificadores imutáveis. Guarde o manifesto anterior e o endereço de suas réplicas. Se modelo e template trocam juntos, trate o conjunto como a unidade do primeiro rollout e isole cada mudança depois no diagnóstico.', 'Reabra uma conversa criada pela versão anterior, incluindo chamadas de ferramenta antigas. Resultado funcional idêntico em prompts novos não testa compatibilidade com o estado que já existe.', 'Rollback precisa incluir dados e contratos de sessão, além do binário.'],
      [0, 'Ensaiar', 'Bloqueie regressões conhecidas antes do primeiro usuário', 'Uma suíte fixa cobre 800 exemplos com 24 casos obrigatórios.', [['Casos','800'],['Críticos','24'],['Falhas críticas','0']], 'Reproduza entradas por idioma, tamanho, uso de ferramentas e histórico. Meça qualidade rotulada, parse, segurança de execução e latência. Os casos obrigatórios incluem a continuação de conversas abertas no manifesto anterior.', 'O resultado zero em 24 casos só informa esses casos. Acrescente testes de capacidade e recuperação de estado. Congele critérios e limites antes de olhar os resultados do tráfego online.', 'Escrever o critério antes da exposição evita aceitar o candidato mudando a régua.'],
      [1, 'Espelhar', 'Envie shadow sem executar efeitos reais', 'Uma amostra de 2% replica 4 req/s para o candidato.', [['Taxa total','200 req/s'],['Shadow','4 req/s'],['Escritas externas','0']], 'Copie entradas autorizadas para processamento assíncrono usando ferramentas simuladas ou somente leitura. A resposta continua vindo do controle. Registre a divergência por classe e limite os recursos de shadow para não degradar o serviço principal.', 'Cache quente, comportamento de usuários após ler respostas e disputas de recursos podem diferir do ambiente real. Separe filas, índices de escrita e credenciais para que uma operação em shadow não altere a produção.', 'Shadow mede comportamento em entradas reais enquanto preserva a resposta de referência.'],
      [1, 'Expor', 'Mantenha a conversa estável ao atribuir a coorte', '1% do tráfego de pico recebe a revisão candidata.', [['Canário','2 req/s'],['Janela','600 s'],['Pedidos esperados','1.200']], 'Atribua por hash estável de conversa ou usuário conforme a unidade de análise. Reserve tráfego de controle equivalente em período e composição. Registre versão em cada resposta e mantenha o backend antigo aquecido.', 'Examine o volume efetivo por segmento. Se apenas 2% dos pedidos usam uma ferramenta rara, são esperados só 24 desses no canário inicial. Aumente amostra dirigida ou tempo de observação antes de interpretar o resultado.', 'O percentual no roteador determina exposição. A precisão da comparação depende do volume observado.'],
      [2, 'Segmentar', 'A taxa geral esconde falha no fluxo de ferramenta', 'Três das 24 chamadas raras do canário falham no parse.', [['Falhas raras','3/24'],['Falhas agregadas','3/1.200'],['Falha no segmento','12,5%']], 'A contribuição ao agregado é 0,25 ponto percentual, porém a experiência do subgrupo pode estar degradada. Compare o controle simultâneo para a mesma ferramenta e reúna mais casos independentes com replay rotulado.', 'Procure o discriminador da falha. Nos três casos aparece o schema antigo do argumento de data. Registre a ação do usuário que ficou incompleta. Um HTTP 200 com argumentos inválidos é falha do produto.', 'Regressões concentradas em fluxos raros podem passar sob um limite agregado.'],
      [2, 'Reverter', 'Retire a nova revisão e preserve rastreabilidade', 'O roteador fecha novas entradas do canário após 45 s.', [['Exposição','1% → 0%'],['Propagação','45 s'],['Atingidos extras','≈90 req']], 'A 2 req/s de canário, 45 s de propagação podem expor aproximadamente mais 90 requisições. Desative novas conversas nessa versão, conclua ou interrompa com regra explícita as sessões em andamento e preserve o vínculo com o manifesto para auditoria.', 'Confirme queda da contagem real de respostas da versão candidata. O rollback da configuração não desfaz uma ferramenta já executada nem garante que todos os proxies leram a mudança.', 'Meça o tempo até a última resposta da versão revertida, além do tempo até o comando ser enviado.'],
      [1, 'Corrigir', 'Republique a correção com uma coorte dirigida', 'O novo teste reúne 300 conversas da ferramenta rara.', [['Casos raros','300'],['Erros de schema','0'],['Manifesto','rev. 43']], 'Normalize os argumentos de acordo com o contrato antes de chamar a ferramenta e preserve o adaptador das conversas antigas. Inclua as três falhas originais, variações de idioma e campos opcionais na suíte.', 'Zero falhas em 300 ensaios independentes dá limite superior aproximado de 1% para a taxa pelo critério de três sobre n a 95%. Se a exigência for inferior a isso, aumente a amostra. Mensagens repetidas da mesma conversa reduzem independência.', 'A evidência necessária depende da taxa de falha que o negócio consegue tolerar.'],
      [2, 'Expandir', 'Aumente tráfego com controle e capacidade de retorno', 'A promoção final ocorre após três patamares com métricas estáveis.', [['Patamares','5/25/50%'],['TTFT p95','710 ms'],['Delta de falhas','+0,05 pp']], 'Em cada patamar, compare erro funcional, custo por tarefa concluída, TTFT, fila e a coorte rara. Exija tempo e amostra para detectar a regressão definida. Verifique a capacidade do controle para reassumir o tráfego antes de remover réplicas antigas.', 'Somente após a janela de observação em 100% retire a versão anterior conforme o prazo de rollback. Conserve manifesto, métricas e critérios que fundamentaram a promoção para avaliar a próxima alteração.', 'Canário é um experimento com decisão reversível e denominadores documentados.'],
    ]),
  },
  'rag-em-producao': {
    minutes: 20,
    scenario: 'Uma central com documentos de 40 clientes troca o índice de políticas de reembolso sem suspender atendimento. Há 200 mil documentos e 600 perguntas rotuladas, 100 delas exigem uma versão histórica. Todos os números são de um ensaio hipotético. Só conta como resolvida a resposta que cita evidência autorizada aplicável à data.',
    source: { label: 'Lewis et al. · Retrieval-Augmented Generation', url: 'https://arxiv.org/abs/2005.11401' },
    steps: flow(['Catálogo', 'Recuperação', 'Resposta'], [
      [0, 'Identificar', 'Dê endereço estável a cada edição da política', 'O catálogo passa a distinguir documento, revisão e vigência.', [['Documentos','200 mil'],['Tenants','40'],['Perguntas','600']], 'A política de janeiro dá 30 dias para pedir reembolso. A de junho pode dar outro prazo, mesmo que o arquivo esteja no mesmo endereço. Guarde em cada trecho o documento, a versão, as datas em que valeu e quem pode lê-lo.', 'Para responder sobre um pedido de janeiro, filtre primeiro a data e a permissão. A citação deve abrir a página ou seção daquela versão. Se a busca devolver apenas a política atual, uma fonte verdadeira pode levar a uma orientação errada.', 'Uma citação útil identifica evidência, edição e período de aplicação.'],
      [0, 'Indexar', 'Construa a revisão nova sem misturar embeddings', 'O índice B é criado ao lado do índice A ainda em produção.', [['Índices','2'],['Cobertura B','96%'],['Faltantes','8.000 docs']], 'Faça snapshot do catálogo e reindexe em paralelo com a ingestão incremental. Grave revisão do encoder, estratégia de chunk e watermark aplicado. Chaves idempotentes evitam duplicação se um worker repetir o processamento.', '96% de cobertura deixa 8 mil documentos ausentes. Compare por tenant e por tipo de documento e liste o que falta. Um grande cliente com documentação simples pode inflar a cobertura e esconder um tenant inteiro sem resultados.', 'Prontidão do índice precisa considerar documentos autorizados e não só quantidade de vetores.'],
      [1, 'Buscar', 'Compare fontes de candidatos sob o filtro correto', 'A busca híbrida melhora a cobertura das perguntas históricas.', [['Históricas','100'],['Recall@20 lexical','0,71'],['Recall@20 híbrido','0,88']], 'A consulta determina tenant, permissões e data antes da recuperação. Combine resultados lexicais, úteis para códigos de política, com vizinhança vetorial para paráfrases. Agregue os rankings sem assumir que os scores dos métodos usam a mesma escala.', 'Para cada questão histórica, confira se ao menos um trecho autorizado de referência está entre os vinte. Audite separadamente as revisões indevidas que entraram no conjunto. A ausência de resposta elegível precisa chegar à geração como ausência de evidência.', 'Medir recuperação antes da geração permite localizar perguntas que o modelo jamais conseguiria responder com as fontes recebidas.'],
      [1, 'Ordenar', 'O reranker precisa manter a exceção do contrato', 'O corte reduz vinte trechos para quatro e remove evidência em nove casos.', [['Candidatos','20'],['Contexto final','4'],['Históricas cobertas','79/100']], 'Reordene os candidatos com o par pergunta-trecho e elimine duplicatas de seções equivalentes. Para exceções contratuais, inclua a cláusula específica e o contexto vizinho necessário para interpretá-la. Controle tokens e latência no estágio de reranking.', 'Nos 88 casos com evidência entre vinte, só 79 a mantiveram nos quatro finais. Examine o conjunto de nove perdas antes de mexer no prompt. Experimente reranking por seção e compare na mesma amostra.', 'O corte do contexto é uma segunda oportunidade de perder a evidência encontrada.'],
      [2, 'Apoiar', 'Exija vínculo entre afirmação e trecho', 'O gerador entrega 73 respostas históricas fundamentadas entre as 79 com evidência.', [['Com evidência','79'],['Fundamentadas','73'],['Falhas com evidência','6']], 'Construa o contexto com IDs de trechos autorizados e peça que cada condição relevante seja sustentada por uma fonte. Verifique se o ID existe na lista retornada, se a fonte segue acessível e se o trecho realmente diz o que a resposta afirma.', 'Faça avaliação humana em amostra com revisão vigente, data e cláusula de exceção visíveis. Separe erro de citação, síntese incorreta e abstenção indevida. Contar links clicáveis mede apenas a existência de links.', 'Busca e geração têm denominadores diferentes. Mostre cada estágio da perda de qualidade.'],
      [0, 'Revogar', 'Um documento deixa de ser visível durante a atualização', 'A ACL vigente na origem muda antes de o índice B receber o evento.', [['Atraso de índice','34 s'],['Trechos antigos','5'],['Permitidos agora','0']], 'Aplique revogação na fonte de autorização e invalide caches relacionados. Faça a checagem final dos candidatos ao montar contexto e também ao servir a citação. Uma janela de atraso da replicação é suficiente para uma resposta usar a permissão anterior.', 'Reproduza uma revogação entre recuperação e montagem de contexto. Remova a evidência que perdeu acesso e refaça a decisão de responder ou abster. Prefira um resultado incompleto a uma política inexistente para aquele usuário.', 'O índice acelera a busca. A permissão vigente deve continuar impondo limites à leitura.'],
      [1, 'Comparar', 'Observe A e B até o mesmo watermark', 'As duas versões têm cobertura completa e diferença de atualização inferior a 2 s.', [['Cobertura B','100%'],['Lag de ingestão','2 s'],['Shadow','5%']], 'Reproduza consultas no mesmo ponto de atualização e compare por tenant, idioma e data. Marque o ID do índice e a revisão dos componentes nos traces. O shadow usa o mesmo escopo de autorização e descarta a resposta gerada.', 'Considere latência, custo de reranking e proporção de respostas fundamentadas. Um índice com melhores embeddings pode ganhar recall e piorar a cauda se exigir candidatos demais para o reranker.', 'Dois índices em watermarks diferentes confundem mudança de modelo com mudança de conteúdo.'],
      [2, 'Promover', 'Troque o alias com regra explícita de recuo', 'Após corrigir o reranking, 87 das 100 questões históricas têm resposta fundamentada.', [['Históricas corretas','87/100'],['Vazamento em teste','0/600'],['Latência p95','940 ms']], 'Mova o alias em canário e mantenha o índice anterior recebendo atualizações até terminar a janela de rollback. Se a cobertura ou a autoridade cair, volte o alias e preserve tombstones e revogações correntes nos dois caminhos.', 'Zero violações na amostra exige continuidade de testes de isolamento e auditoria de revogação. Acompanhe perguntas sem fonte, tempo de atualização e custo por resposta resolvida. Reavalie a amostra quando houver mudança de conteúdo ou distribuição de clientes.', 'Rollback do índice recupera a revisão anterior sem desfazer as regras atuais de acesso.'],
    ]),
  },
  'inferencia-em-lote': {
    minutes: 20,
    scenario: 'O time precisa classificar 12 milhões de itens em quatro horas. No teste, cada processo classifica 60 por segundo. Uma lista de arquivos indica o que ficou pronto mesmo se um processo parar.',
    source: { label: 'Ray Data · inferência offline de ponta a ponta', url: 'https://docs.ray.io/en/latest/data/batch-inference.html' },
    steps: flow(['Manifesto', 'Workers', 'Publicação'], [
      [0, 'Congelar', 'Defina o que compõe a execução', 'Um manifesto fixa entrada, modelo e transformação.', [['Itens únicos','12 mi'],['Prazo','4 h'],['Mínimo médio','834 itens/s']], 'Associe cada item a uma revisão imutável da entrada. O manifesto inclui snapshot da origem, modelo, template, parâmetros de geração e tolerância a erros. 12 milhões divididos por 14.400 s exigem cerca de 833,3 itens/s úteis.', 'A contagem deve distinguir itens únicos de linhas brutas. Defina a chave de resultado por item e revisão do pipeline e preserve o manifesto anterior até concluir a publicação. Uma geração interrompida pode ser retomada sobre o mesmo conjunto.', 'Um replay reproduz a execução somente se todas as entradas de negócio estiverem identificadas.'],
      [1, 'Dimensionar', 'Reserve capacidade além do mínimo teórico', 'Dezesseis workers produzem 960 itens/s antes de falhas.', [['Workers','16'],['Capacidade','960 itens/s'],['Tempo ideal','3 h 28 min']], 'O mínimo aritmético é teto de 833,3/60, ou 14 workers. Com 14, o tempo ideal é quase 4 h e resta pouca margem. Com 16, o ensaio ideal termina em 12.500 s, deixando cerca de 31 min e 40 s.', 'Observe leitura, tokenização, GPU e escrita em separado. Refaça o teste com a distribuição de comprimentos real. A multiplicação linear por worker pressupõe que storage e sink acompanharão o aumento de paralelismo.', 'Planeje itens publicados dentro do prazo, não apenas tokens gerados pela GPU.'],
      [1, 'Particionar', 'Equilibre custo sem perder a identidade dos itens', 'Doze mil partições de mil itens simplificam o primeiro ensaio.', [['Partições','12.000'],['Itens/bloco','1.000'],['Bloco médio','16,7 s']], 'Atribua identidade estável a cada bloco e distribua dinamicamente para workers com o modelo já carregado. Para texto, agrupe comprimentos parecidos dentro dos lotes e distribua os lotes longos entre partições. Isso reduz padding e cauda sem trocar chaves.', 'Meça p95 e máximo da duração por bloco. Entradas ordenadas por tamanho podem criar uma última partição muito pesada. Estime também o custo de reiniciar um bloco inteiro antes de aumentar a granularidade.', 'Partições pequenas barateiam replay e aumentam overhead de coordenação.'],
      [2, 'Confirmar', 'Grave dados antes do marcador de publicação', 'Um bloco só entra no manifesto após conferir mil IDs únicos.', [['Saídas esperadas','1.000'],['IDs verificados','1.000'],['Commit lógico','1']], 'Cada tentativa grava em um caminho próprio de staging e calcula checksum e contagem. Um coordenador faz inserção única ou compare-and-swap do commit por partição e versão. Os leitores seguem o manifesto e ignoram tentativas não confirmadas.', 'Force a queda depois de gravar o arquivo e antes de registrar o commit. O reprocessamento pode produzir outro arquivo; a regra de publicação garante um único resultado visível. Remova órfãos só depois da janela de recuperação.', 'Persistir um arquivo e torná-lo parte da versão publicada são operações diferentes.'],
      [1, 'Repetir', 'A interrupção de workers deixa blocos com estado incerto', 'Quatro workers caem durante quatro blocos ainda sem commit.', [['Workers perdidos','4'],['Blocos a rever','4'],['Itens reprocessáveis','4.000']], 'Recupere os commits duráveis e reenfileire somente blocos sem confirmação. O checkpoint de processamento do framework e a confirmação no sink têm objetivos diferentes. A regra do manifesto protege contra o worker antigo voltar a escrever depois do substituto.', 'Dê a cada tentativa uma geração ou um lease e recuse um commit de geração antiga após a substituição. Compare o número de tentativas com o número de itens efetivamente publicados para estimar a taxa de trabalho repetido.', 'Execução pode ocorrer mais de uma vez enquanto a publicação por revisão permanece única.'],
      [0, 'Quarentenar', 'Separe entradas ruins de falhas temporárias', 'Uma partição contém três entradas que sempre falham na validação.', [['Itens do bloco','1.000'],['Determinísticos','3'],['Válidos','997']], 'Identifique erros permanentes como formato inválido ou entrada acima de um limite explícito. Divida o bloco para isolar esses itens e registre-os com motivo e revisão. Limite tentativas de erros transitórios com prazo total.', 'Se a política exige 100% classificados, a presença de três itens inválidos bloqueia a publicação. Se permite exceções, publique as 997 saídas e três registros de quarentena contabilizados. Torne esse acordo verificável por consumidor.', 'Ignorar silenciosamente a linha ruim quebra a correspondência entre manifesto e resultado.'],
      [1, 'Replanejar', 'Recalcule o ETA com vazão efetivamente confirmada', 'Faltam 3,6 milhões de itens quando resta 1 h do prazo.', [['Restantes','3,6 mi'],['Vazão exigida','1.000 itens/s'],['Workers mínimos','17']], 'Com 60 itens/s úteis por worker, 17 entregam 1.020/s em condições ideais. Se apenas 12 sobreviveram, adicionar cinco repõe a estimativa mínima, sem margem para startup ou novas falhas. Use o ritmo recente de commits, não apenas a taxa declarada no scheduler.', 'Teste aumentar para 19 e acompanhe latência do sink e uso de memória. Se a fila de saída crescer e a taxa de commits não subir, habilitar mais GPU aumenta custo sem recuperar o prazo.', 'A etapa mais lenta determina o prazo, inclusive depois de a inferência terminar.'],
      [2, 'Publicar', 'Faça reconciliação antes de trocar a versão visível', 'O manifesto fecha com 11.999.997 resultados e três exceções documentadas.', [['Classificados','11.999.997'],['Quarentena','3'],['IDs faltantes','0']], 'Confirme unicidade por chave, soma de saídas e quarentena, checksum e versão única dos artefatos. Validar apenas contagem pode esconder uma duplicata e um item ausente. Compare conjuntos de IDs ou assinaturas com investigação das divergências.', 'Publique o ponteiro final de forma atômica. Simule um leitor durante a troca e confirme que ele enxerga a versão antiga completa ou a nova completa. Preserve taxa de replay, tempo, custo por item válido e amostra de qualidade no relatório da execução.', 'O lote termina quando o consumidor lê uma versão inteira, consistente e reconciliada.'],
    ]),
  },
  'features-online': {
    minutes: 19,
    scenario: 'Um site faz duas mil recomendações por segundo. O modelo lê 12 informações por pedido. Uma delas é o número de compras dos últimos sete dias. Vamos testar o que acontece quando uma compra demora a aparecer nesse contador.',
    source: { label: 'Feast · point-in-time joins e TTL histórico', url: 'https://docs.feast.dev/getting-started/concepts/point-in-time-joins' },
    steps: flow(['Evento', 'Materialização', 'Predição'], [
      [0, 'Definir', 'Fixe o instante que a previsão pode conhecer', 'A feature tem janela de sete dias e chave por usuário e marketplace.', [['Features','12'],['Janela','7 dias'],['Taxa','2.000/s']], 'Defina chave de entidade, relógio de evento, regra de atraso, tipo e valor para entidade nova. Um mesmo usuário pode ter comportamentos diferentes em dois marketplaces. Registre a revisão da definição e o contrato de frescor na publicação.', 'Para uma previsão às 10h, reconstrua o intervalo de sete dias com bordas explícitas. Diferencie o horário econômico da compra do horário em que o pipeline soube dela. Os dois determinam o que era possível servir.', 'Uma feature é o valor junto com chave, semântica temporal e revisão.'],
      [0, 'Reconstruir', 'Impeça que o treino use o futuro', 'Uma compra às 09h58 só ingressou às 10h07.', [['Hora do evento','09h58'],['Disponível','10h07'],['Previsão','10h00']], 'O join point-in-time recupera o valor mais recente disponível no histórico conforme o timestamp usado e o TTL da feature. Se o treino reconstrói tudo pelo tempo de evento após um backfill, pode incluir uma compra que ainda não havia chegado às 10h.', 'Preserve o tempo de disponibilidade ou uma versão histórica publicada. Para este caso, o replay precisa excluir a compra de 09h58 na previsão de 10h00 e incluí-la após a ingestão, conforme a política definida.', 'Um join por tempo de evento sozinho não reconstrói a informação conhecida antes da chegada de eventos atrasados.'],
      [1, 'Materializar', 'Torne a escrita online monotônica por entidade', 'A revisão das 10h08 chega ao armazenamento antes de um replay das 10h03.', [['Revisão vigente','10h08'],['Replay antigo','10h03'],['Atualizações aceitas','1']], 'Publique o agregado validado com versão de cálculo e timestamp de origem. Quando houver eventos concorrentes, aplique uma escrita condicional comparando a revisão persistida. Um replay antigo não deve sobrescrever a correção mais recente.', 'Reproduza as duas ordens de entrega e compare o valor final. Decida como uma correção legítima de um evento antigo ganha uma revisão de publicação nova. Ordenar apenas pelo timestamp original pode descartar essa correção.', 'Separar versão de publicação de tempo do fato permite corrigir dados sem regressão de estado.'],
      [2, 'Servir', 'Busque o vetor em lote e registre a idade', 'Uma leitura agrupada substitui doze acessos individuais por previsão.', [['Leituras antes','24 mil/s'],['Chamadas após','2 mil/s'],['Valores/s','24 mil']], 'Agrupe os 12 atributos em uma chamada por previsão quando o backend permitir. Isso reduz viagens de rede, embora o volume de valores e o custo interno possam permanecer altos. Registre a idade de cada atributo e identifique ausência explicitamente.', 'Meça p95 do vetor completo com a mesma cardinalidade e concentração de chaves da produção. Leituras agrupadas entre shards podem ter cauda determinada pela partição mais lenta. Evite preencher todos os campos ausentes com zero sem sinalizar ao modelo.', 'Quantidade de chamadas, valores buscados e custo por partição são métricas distintas.'],
      [1, 'Diagnosticar', 'A entrega continua rápida enquanto os dados envelhecem', 'O p95 de leitura é 11 ms, mas 18% dos vetores têm idade acima da meta.', [['Busca p95','11 ms'],['Idade exigida','≤15 min'],['Fora da meta','18%']], 'Os servidores respondem do cache, então o painel de latência permanece verde. O consumidor de uma partição atrasou após o rebalanceamento. Compare watermark da origem, último evento processado, escrita online e leitura do serviço por partição.', 'Verifique a distribuição por marketplace e entidade. Um usuário inativo pode ter um valor antigo válido; monitore também o progresso do pipeline e a semântica da feature para não confundir inatividade com incidente de atualização.', 'Disponibilidade do armazenamento não mede frescor da informação.'],
      [2, 'Degradar', 'Escolha fallback treinado para a feature vencida', 'Ative uma variante que usa 11 atributos para os casos afetados.', [['Atributos usados','11'],['Fallback','18%'],['Busca p95','12 ms']], 'Somente se a variante tiver sido treinada e avaliada sem a feature de compras, use-a para os vetores vencidos. Outra opção prevista pelo produto pode ser um ranking de popularidade. Registre qual política foi usada junto ao ID da previsão.', 'Compare conversão e qualidade por coorte enquanto drena a fila. Não misture previsões da variante em dados rotulados sem capturar sua origem. Resultado futuro chega depois e não serve como sinal imediato único para voltar ao modelo principal.', 'Dados fora do contrato precisam de um caminho de produto previsível e observável.'],
      [1, 'Reparar', 'Reprocesse a lacuna em uma versão candidata', 'Um backfill cobre 90 min sem interromper o caminho online.', [['Lacuna','90 min'],['Partições afetadas','2'],['Paridade amostral','996/1.000']], 'Parta do último checkpoint confiável, deduplique por ID de evento e recalcule em namespace separado. Compare amostras online com a reconstrução offline no mesmo instante de disponibilidade. Inclua entidades novas, correções tardias e janelas vazias.', 'Examine as quatro divergências antes de trocar o ponteiro. Aqui a causa testada é uma borda inclusiva no cálculo online e exclusiva no offline. Corrija a definição nas duas materializações e repita o teste com compras exatamente no limite.', 'O mesmo nome de feature pode esconder semânticas diferentes no treino e no serving.'],
      [2, 'Retomar', 'Volte à versão completa em coortes', 'A versão reparada restaura os 12 atributos com frescor e latência dentro da meta.', [['Paridade','1.000/1.000'],['Fora da meta','0,1%'],['Busca p95','14 ms']], 'Volte primeiro para uma fatia da frota com métricas por marketplace. Registre revisões da feature e do modelo, idade e uso de fallback para cada previsão amostrada. Mantenha a versão anterior até observar atraso do pipeline ao longo de uma janela representativa.', 'Valide a recuperação com carga de 2 mil/s e reentrega de eventos fora de ordem. Monitore qualidade depois da chegada dos rótulos. A amostra com paridade total comprova aquele conjunto, enquanto testes de borda e monitoramento cobrem alterações futuras.', 'Uma previsão reproduzível requer também a versão e a disponibilidade dos valores que o serviço leu.'],
    ]),
  },
};
